      SdkOptional<String> endTime = const SdkOmitted(),
      SdkOptional<int> limit = const SdkOmitted(),
      SdkOptional<String> cursor = const SdkOmitted(),
      SdkOptional<ProjectBranchLogsQueryRequestSortOrder> sortOrder =
